def transform(grid):
    # Across the demonstrations, the smaller of the two colors becomes zero;
    # the larger color becomes the smaller color.
    colors = sorted({v for row in grid for v in row})
    if len(colors) != 2:
        raise ValueError("expected a two-color grid")
    low, high = colors
    return [[0 if v == low else low for v in row] for row in grid]
